<?php
require __DIR__.'/bootstrap.php';
requireAuth();
$stats=['products'=>0,'active'=>0,'drafts'=>0,'low_stock'=>0,'collections'=>0,'images'=>0,'variants'=>0,'admins'=>0];$recent=[];$dbError=false;
try{
 $pdo=db();
 $stats['products']=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();
 $stats['active']=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE status='active'")->fetchColumn();
 $stats['drafts']=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE status='draft'")->fetchColumn();
 $stats['low_stock']=(int)$pdo->query("SELECT COUNT(*) FROM product_variants WHERE is_active=1 AND availability_mode='stock' AND stock_qty BETWEEN 0 AND 3")->fetchColumn();
 $stats['collections']=(int)$pdo->query('SELECT COUNT(*) FROM collections WHERE is_active=1')->fetchColumn();
 $stats['images']=(int)$pdo->query('SELECT COUNT(*) FROM product_images')->fetchColumn();
 $stats['variants']=(int)$pdo->query('SELECT COUNT(*) FROM product_variants')->fetchColumn();
 if(canManageUsers())$stats['admins']=(int)$pdo->query('SELECT COUNT(*) FROM admin_users WHERE is_active=1')->fetchColumn();
 if(canViewAudit())$recent=$pdo->query('SELECT action,entity_type,created_at FROM admin_audit_log ORDER BY created_at DESC LIMIT 10')->fetchAll();
}catch(Throwable $e){error_log('InYou admin dashboard: '.$e->getMessage());$dbError=true;}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel · InYou</title><link rel="stylesheet" href="/admin/style.css"><style>.quick{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}.quick a{display:block;background:#fff;border:1px solid #e5e2db;border-radius:10px;padding:18px;text-decoration:none;color:#20211f}.quick strong{display:block;margin-bottom:6px}.quick small{color:#777}.role-note{display:inline-block;margin-left:8px;padding:4px 8px;border-radius:999px;background:#f1f0eb;font-size:12px;color:#666}@media(max-width:800px){.quick{grid-template-columns:1fr}}</style></head><body class="dashboard"><?php adminSidebar('home');?><main class="content"><header><div>Hola, <?=h($_SESSION['admin_name']??'Administrador')?> <span class="role-note"><?=h(role())?></span></div><form method="post" action="/admin/logout.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="signout">Cerrar sesión</button></form></header><div class="eyebrow">RESUMEN GENERAL</div><h1>Dashboard</h1><p>Estado del catálogo e inventario según los permisos de tu usuario.</p><?php if($dbError):?><div class="error">No se pudo cargar toda la información. Revisá la conexión y la estructura de la base.</div><?php endif;?><section class="cards"><article><small>Productos activos</small><strong><?=h((string)$stats['active'])?></strong></article><article><small>Variantes</small><strong><?=h((string)$stats['variants'])?></strong></article><article><small>Stock bajo (0–3)</small><strong><?=h((string)$stats['low_stock'])?></strong></article><article><small>Colecciones activas</small><strong><?=h((string)$stats['collections'])?></strong></article></section><section class="quick"><a href="/admin/products.php"><strong>Productos</strong><small>Alta, edición, publicación, variantes e imágenes.</small></a><a href="/admin/inventory.php"><strong>Inventario</strong><small>Vista central de SKU, stock y bajo pedido.</small></a><a href="/admin/collections.php"><strong>Colecciones</strong><small>Organización del catálogo público.</small></a><a href="/admin/media.php"><strong>Medios</strong><small>Biblioteca de imágenes del catálogo.</small></a><?php if(canManageSettings()):?><a href="/admin/settings.php"><strong>Configuración</strong><small>Tienda, WhatsApp y activación comercial.</small></a><?php endif;?><?php if(canViewAudit()):?><a href="/admin/audit.php"><strong>Auditoría</strong><small>Historial de cambios y responsables.</small></a><?php endif;?><?php if(canManageUsers()):?><a href="/admin/users.php"><strong>Usuarios</strong><small>Accesos individuales, roles y contraseñas.</small></a><?php endif;?><a href="/" target="_blank" rel="noopener"><strong>Ver tienda</strong><small>Abrir catálogo público en otra pestaña.</small></a></section><section class="panels"><article><h2>Catálogo</h2><p><?=h((string)$stats['products'])?> productos · <?=h((string)$stats['images'])?> imágenes · <?=h((string)$stats['drafts'])?> borradores.</p><div class="empty"><p>El panel administra el catálogo aprobado sin habilitar operaciones financieras.</p><a href="/admin/products.php">Gestionar catálogo →</a></div></article><?php if(canViewAudit()):?><article><h2>Actividad reciente</h2><?php if(!$recent):?><div class="empty">Todavía no hay actividad registrada.</div><?php else:?><ul><?php foreach($recent as $r):?><li><?=h($r['action'])?> · <?=h($r['entity_type'])?> <small><?=h($r['created_at'])?></small></li><?php endforeach;?></ul><?php endif;?></article><?php endif;?></section><p class="notice">Entorno de desarrollo · El panel no ejecuta pagos ni confirma ventas.</p></main></body></html>